"""Document/provenance checks only; no domain execution or acceptance."""
from pathlib import Path
import collections
import datetime
import difflib
import hashlib
import json
import subprocess
import traceback

ROOT = Path('F:/ChnobelRuntime/reviews/v2-manifest-questions-03/u07')
MANIFEST = Path('F:/ChnobelRuntime/specification/v2-manifest-draft-01')
REPO = Path('F:/Projects/Chnobel')
OUT = Path(__file__).parent
BASE = '229fb3bd52f0473af5aeb9ead023df3db63c6847'
BEFORE = '299cea2c502a370e4128bb2bd77d48787e4c7dcc'
BRIEF_SHA = 'e26814fe066372316a2e5a1a0d80ee81391e0eadd2a48e46aade902b33bb9231'
INPUT_SHA = '9878ae90f1cbb6c0df5af7b26460fd60b6911f3ab4115cf51d9200c19986aba0'
SKILL_OLD = '31f5703f1a1ddda1b5645d5c202f1f7e507aee96dbe559ff272e2f191d7b07489'
SKILL_NEW = '07ebb533107fe49ff61158920fa5fe97d416a83d6aafbf423e00445ca9bc2263c'
SKILL_INSERT = '- Record a later narrow technical acceptance in a separate hash-bound decision after verifying and losslessly preserving the complete foreign reviews. Keep the frozen proposal\'s historical unaccepted status unchanged. Resolve only the exact textual/source defect demonstrated fixed; separately track all retained inventory, acquisition, enforcement and whole-manifest integration obligations. A prescribed separate gate is neither an implemented service nor an executed success, and narrow acceptance cannot authorise product implementation.\n'


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def load(path):
    return json.loads(Path(path).read_bytes())


def binding(path):
    p = Path(path)
    raw = p.read_bytes()
    return {'path': p.as_posix(), 'sha256': sha(raw), 'bytes': len(raw)}


def project(b):
    return {k: Path(b[k]).as_posix() if k == 'path' else b[k]
            for k in ('path', 'sha256', 'bytes')}


def check(b):
    assert binding(b['path']) == project(b), b['path']


def pointer(value, address):
    for part in address.split('/')[1:]:
        key = part.replace('~1', '/').replace('~0', '~')
        value = value[int(key)] if isinstance(value, list) else value[key]
    return value


def git(*args):
    return subprocess.check_output(['git', '-C', str(REPO), *args])


def write_new(path, value):
    assert not path.exists(), path
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2) + '\n', encoding='utf-8', newline='\n')


def rawbound(raw, b):
    assert sha(raw) == b['sha256'] and len(raw) == b['bytes'], b


def forward_diff(before, after, diff):
    result, cursor, out_cursor = [], 0, 0
    for op in diff['operations']:
        a, b = op['beforeCharStart'], op['beforeCharEnd']
        c, d = op['afterCharStart'], op['afterCharEnd']
        assert cursor <= a <= b and out_cursor <= c <= d
        assert before[cursor:a] == after[out_cursor:c]
        assert before[a:b] == op['removedUtf8']
        assert after[c:d] == op['insertedUtf8']
        result.extend((before[cursor:a], op['insertedUtf8']))
        cursor, out_cursor = b, d
    result.append(before[cursor:])
    assert ''.join(result) == after


def restore_after(lines, expected_raw):
    assert ''.join(difflib.restore(lines, 2)).encode('utf-8') == expected_raw
    return ''.join(difflib.restore(lines, 1)).encode('utf-8')


def main():
    assert git('rev-parse', 'HEAD').decode().strip() == BASE
    assert not git('status', '--porcelain=v1', '--untracked-files=all')
    assert binding(ROOT / 'brief.md')['sha256'] == BRIEF_SHA
    assert binding(ROOT / 'input-bindings.json')['sha256'] == INPUT_SHA
    inputs = load(ROOT / 'input-bindings.json')
    required = {x['path']: x for x in inputs['mandatoryFiles']}
    assert len(required) == len(inputs['mandatoryFiles']) == 53
    for b in required.values():
        check(b)
    check(inputs['manifest'])
    check(inputs['manifestHandoff'])
    catalogue = load(MANIFEST / 'catalogue.json')
    facts = {x['id'] for x in catalogue['facts']}
    claims = {x['id'] for x in catalogue['claims']}
    handoff = load(inputs['manifestHandoff']['path'])
    original_files = {str((MANIFEST / x['path']).as_posix()): x for x in handoff['files']}
    assert len(original_files) == len(handoff['files']) == 4944
    selected = {x['caseId']: x for x in inputs['selectedCases']}
    variants = {x['caseId']: x for x in inputs['transportVariants']}
    assert len(selected) == 4 and len(variants) == 8
    assert len(inputs['originalIndexProjections']) == 12
    for p in inputs['originalIndexProjections']:
        original = pointer(load(p['sourceIndex']), p['pointer'])
        assert original['id'] == p['caseId']
        assert original['input'] == p['input'] and original['oracle'] == p['oracle']
        check(p['absoluteInput']); check(p['absoluteOracle'])
    for p in inputs['historicalProjections']:
        assert pointer(load(p['sourceIndex']), p['pointer'])['path'] == p['path']
        check({'path': p['absolutePath'], 'sha256': p['sha256'], 'bytes': p['bytes']})
    variant_checks = []
    for case_id, p in variants.items():
        b = selected[p['baseCaseId']]
        base_input, variant_input = load(b['input']['path']), load(p['input']['path'])
        expected = load(p['oracle']['path'])
        events, delivered = base_input['events'], variant_input['events']
        event_map = {e['id']: e for e in events}
        assert all(e == event_map[e['id']] for e in delivered)
        counts = collections.Counter(e['id'] for e in delivered)
        assert set(counts) == set(event_map)
        assert set(counts.values()) == ({2} if p['transform'] == 'redelivery' else {1})
        assert {k: v for k, v in variant_input.items() if k != 'events'} == {k: v for k, v in base_input.items() if k != 'events'}
        oracle_ref = expected['baseOracle']
        assert (MANIFEST / oracle_ref['path']).as_posix() == b['oracle']['path']
        assert oracle_ref['sha256'] == b['oracle']['sha256'] and oracle_ref['bytes'] == b['oracle']['bytes']
        check(b['oracle'])
        actual_counts = {'delivered': len(delivered), 'uniqueIds': len(counts), 'duplicateDeliveries': len(delivered) - len(counts)}
        assert all(expected['integrityCounts'][k] == n for k, n in actual_counts.items())
        variant_checks.append({'caseId': case_id, 'documentCounts': actual_counts, 'result': 'RAW_EVENT_AND_ORACLE_LINKS_MATCH'})
    roles, drift_snapshots = {}, []
    for role in ('didaktik', 'architekt'):
        folder = ROOT / role
        assert {p.name for p in folder.iterdir()} == {'report.md', 'sources.json', 'decision.json'}
        source, decision = load(folder / 'sources.json'), load(folder / 'decision.json')
        assert decision['status'] == 'COMPLETE' and decision['questionId'] == 'Q-U07'
        assert decision['wholeRoleStatus'] == 'INCOMPLETE_OTHER_QUESTIONS_PENDING'
        assert decision['wholeManifestVerdict'] == 'NOT_ISSUED'
        assert decision['implementationAuthorized'] is False and decision['blockerClosed'] is False
        assert 600 <= len((folder / 'report.md').read_text(encoding='utf-8').split()) <= 1600
        if role == 'didaktik':
            for b in source['outputBindings'].values(): check(b)
            check(decision['report']); check(decision['sources'])
        else:
            for b in decision['outputBindings'].values(): check(b)
        mandatory = source['mandatoryFiles']
        assert len(mandatory) == 53 and {x['expected']['path'] for x in mandatory} == set(required)
        for entry in mandatory:
            wanted = required[entry['expected']['path']]
            assert project(entry['expected']) == project(wanted)
            assert project(entry['before']) == project(wanted)
            assert project(entry['after']) == project(wanted)
            assert entry['readScope']
        changed_skills = []
        for entry in source['additionalSources']:
            before, after = entry['before'], entry['after']
            assert project(before) == project(entry['expected'])
            check(after)
            if before['sha256'] != after['sha256']:
                assert before['sha256'] == SKILL_OLD and after['sha256'] == SKILL_NEW
                changed_skills.append(entry)
            else:
                assert project(before) == project(after)
        assert len(changed_skills) == 1
        drift = source['sourceDeviations']
        if role == 'didaktik':
            assert len(drift['unexpectedOutsideAllowedMutableParents']) == 1
            deviation = drift['unexpectedOutsideAllowedMutableParents'][0]
        else:
            assert len(drift) == 1
            deviation = drift[0]
        current_skill = Path(changed_skills[0]['after']['path']).read_bytes()
        assert current_skill.count(SKILL_INSERT.encode('utf-8')) == 1
        old_skill = current_skill.replace(SKILL_INSERT.encode('utf-8'), b'', 1)
        rawbound(old_skill, changed_skills[0]['before'])
        if role == 'didaktik':
            forward_diff(old_skill.decode('utf-8'), current_skill.decode('utf-8'), deviation['beforeToAfterRawDiff'])
        else:
            reverse = deviation['afterToBeforeRawDiff']
            rebuilt = current_skill.decode('utf-8')[:reverse['afterOffsetCharacters']] + reverse['beforeReplacementText'] + current_skill.decode('utf-8')[reverse['afterOffsetCharacters'] + reverse['afterSegmentCharacters']:]
            assert rebuilt.encode('utf-8') == old_skill
        drift_snapshots.append({'role': role, 'before': changed_skills[0]['before'], 'after': changed_skills[0]['after'], 'beforeUtf8': old_skill.decode('utf-8'), 'afterUtf8': current_skill.decode('utf-8'), 'insertedText': SKILL_INSERT, 'classification': 'EXPLAINED_PARENT_PROCEDURAL_EDIT_OUTSIDE_ORIGINAL_MUTABLE_ALLOWLIST', 'retroactivePermission': False})
        mutable = source['mutableParentContexts']
        expected_contexts = {x['path']: x for x in inputs['mutableContextsBefore']}
        assert len(mutable) == 3 and {x['expected']['path'] for x in mutable} == set(expected_contexts)
        for entry in mutable:
            path = entry['expected']['path']
            before_raw = expected_contexts[path]['utf8Raw'].encode('utf-8')
            after_raw = Path(path).read_bytes()
            rawbound(before_raw, entry['expected']); rawbound(before_raw, entry['before']); rawbound(after_raw, entry['after'])
            relative = Path(path).relative_to(REPO).as_posix()
            assert git('show', BEFORE + ':' + relative) == before_raw.replace(b'\r\n', b'\n')
            assert git('show', BASE + ':' + relative) == after_raw.replace(b'\r\n', b'\n')
            if role == 'didaktik':
                assert entry['before']['utf8Raw'].encode('utf-8') == before_raw
                assert entry['after']['utf8Raw'].encode('utf-8') == after_raw
                forward_diff(before_raw.decode('utf-8'), after_raw.decode('utf-8'), entry['beforeToAfterRawDiff'])
            else:
                assert restore_after(entry['rawDiff']['ndiffLines'], after_raw) == before_raw
        if role == 'didaktik':
            for entry in source['handoffSelectedProjections']['selected']:
                assert pointer(handoff, entry['pointer']) == entry['originalRecord']
                check(entry['mandatoryBinding'])
                assert original_files[entry['mandatoryBinding']['path']] == entry['originalRecord']
            assert len(source['handoffSelectedProjections']['selected']) == 37
        assert len(decision['cases']) == 2
        for case in decision['cases']:
            original = selected[case['caseId']]
            document = load(original['input']['path'])
            event_by_seq = {e['seq']: e for e in document['events']}
            if role == 'didaktik':
                assert {f['factId'] for f in case['factProposals']} == facts
                assert {c['claimId'] for c in case['claimProposals']} == claims
                for observed in case['observedEvents']:
                    actual = pointer(document, observed['pointer'])
                    assert observed['source'] == original['input']['path']
                    assert observed['eventId'] == actual['id']
                    assert all(observed[k] == actual[k] for k in ('seq', 'actor', 'type', 'payload'))
                for observed in case['supportEvidenceObservations']:
                    actual = pointer(document, observed['pointer'])
                    assert observed['evidenceId'] == actual['id']
                    assert all(observed[k] == actual[k] for k in ('channel', 'fromSeq', 'throughSeq', 'coverage', 'signals', 'sceneReference'))
            else:
                assert case['input'] == original['input'] and case['oracle'] == original['oracle']
                for observed in case['observedTraceProjection']:
                    actual = event_by_seq[observed['seq']]
                    assert observed['eventId'] == actual['id']
                    assert observed['actor'] == actual['actor'] and observed['type'] == actual['type']
            def walk(node):
                if isinstance(node, dict):
                    if {'eventId', 'seq'} <= set(node):
                        actual = event_by_seq[node['seq']]
                        assert node['eventId'] == actual['id']
                        if 'type' in node: assert node['type'] == actual['type']
                    for value in node.values(): walk(value)
                elif isinstance(node, list):
                    for value in node: walk(value)
            walk(case)
        roles[role] = {'outputs': [binding(folder / n) for n in ('report.md', 'sources.json', 'decision.json')], 'mandatoryBindingsVerified': 53, 'mutableContextsReconstructed': 3, 'reportWords': len((folder / 'report.md').read_text(encoding='utf-8').split()), 'questionCompletion': 'COMPLETE_CONSULTATION_WITH_RETAINED_PROCEDURAL_DEVIATION', 'wholeRoleStatus': 'INCOMPLETE_OTHER_QUESTIONS_PENDING'}
    for b in required.values(): check(b)
    assert not git('status', '--porcelain=v1', '--untracked-files=all')
    drift_path = OUT / 'procedural-source-drift.json'
    write_new(drift_path, {'scope': 'PROCEDURAL_SOURCE_DRIFT_ONLY', 'normativeSourcesChanged': False, 'allowlistViolationPreserved': True, 'sourceSetAtomic': False, 'snapshots': drift_snapshots})
    result = {'result': 'PASS_DOCUMENT_BINDINGS_WITH_EXPLAINED_PROCEDURAL_DEVIATION', 'scope': 'DOCUMENT_AND_SOURCE_MECHANICS_ONLY', 'at': datetime.datetime.now().astimezone().isoformat(), 'helper': binding(__file__), 'base': BASE, 'brief': binding(ROOT / 'brief.md'), 'inputs': binding(ROOT / 'input-bindings.json'), 'manifest': inputs['manifest'], 'roles': roles, 'originalIndexProjectionsVerified': 12, 'transportLinksVerified': variant_checks, 'proceduralSourceDrift': binding(drift_path), 'wholeReadSetUnchanged': False, 'wholeManifestVerdict': 'NOT_ISSUED', 'blockerClosed': False, 'implementationAuthorized': False, 'productExecution': 'NOT_RUN', 'redTeam': 'PENDING'}
    write_new(OUT / 'verification.json', result)
    print(json.dumps({k: v for k, v in result.items() if k not in ('roles', 'transportLinksVerified')}, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    try:
        main()
    except Exception:
        incident = {'result': 'PARENT_DOCUMENT_HELPER_FAILED', 'helper': binding(__file__), 'traceback': traceback.format_exc(), 'notProductVerdict': True}
        number = 1
        while (OUT / f'attempt-{number:02d}.json').exists(): number += 1
        write_new(OUT / f'attempt-{number:02d}.json', incident)
        raise
